-- Encrypted provider custody. No target, secret, grant or provider write is created here.
BEGIN;
CREATE TABLE public.sandy_credential_targets (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 provider text NOT NULL CHECK(provider IN ('github_actions_secret','supabase_edge_secret','gcp_secret','gcp_service_account_key')),
 resource jsonb NOT NULL CHECK(jsonb_typeof(resource)='object'),
 scope_sha256 text NOT NULL CHECK(scope_sha256 ~ '^[a-f0-9]{64}$'),
 config_sha256 text NOT NULL CHECK(config_sha256 ~ '^[a-f0-9]{64}$'),
 enabled boolean NOT NULL DEFAULT false,
 verified boolean NOT NULL DEFAULT false,
 active_version_id uuid,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.sandy_credential_versions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),target_id uuid NOT NULL REFERENCES public.sandy_credential_targets(id),
 vault_secret_id uuid NOT NULL UNIQUE,
 material_sha256 text NOT NULL CHECK(material_sha256 ~ '^[a-f0-9]{64}$'),
 provider_version_id text CHECK(length(provider_version_id)<=1000),
 state text NOT NULL CHECK(state IN ('staged','active','retained','revoked')),
 source_admission_id uuid NOT NULL REFERENCES public.sandy_api_execution_admissions(id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.sandy_credential_targets ADD CONSTRAINT sandy_credential_targets_active_version_fkey FOREIGN KEY(active_version_id) REFERENCES public.sandy_credential_versions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE public.sandy_credential_rotations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),target_id uuid NOT NULL REFERENCES public.sandy_credential_targets(id),
 actor_id uuid NOT NULL, source_admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id),
 source_operation text NOT NULL CHECK(source_operation IN ('supabase.functions.secrets.rotate','github.repo_secrets.rotate','gcp.secrets.create_version','gcp.secrets.rotate','gcp.service_accounts.keys.rotate','system.credentials.provider.rollback','system.credentials.provider.adopt','gcp.secrets.access')),
 source_version_id uuid REFERENCES public.sandy_credential_versions(id),prior_version_id uuid REFERENCES public.sandy_credential_versions(id),
 staged_version_id uuid REFERENCES public.sandy_credential_versions(id),
 target_config_sha256 text NOT NULL CHECK(target_config_sha256 ~ '^[a-f0-9]{64}$'),
 probe_challenge uuid NOT NULL DEFAULT gen_random_uuid(),probe_started_at timestamptz,
 verification_evidence jsonb,verification_canonical text,
 state text NOT NULL DEFAULT 'claimed' CHECK(state IN ('claimed','accepted','unknown','cleanup_claimed','verified','activated','failed','revoked')),
 provider_version_id text CHECK(length(provider_version_id)<=1000),
 verification_admission_id uuid REFERENCES public.sandy_api_execution_admissions(id),cleanup_admission_id uuid REFERENCES public.sandy_api_execution_admissions(id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.sandy_credential_targets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_credential_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_credential_rotations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_credential_targets,public.sandy_credential_versions,public.sandy_credential_rotations FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public.sandy_credential_targets,public.sandy_credential_versions,public.sandy_credential_rotations TO service_role;

-- Private canonicalization is shared by custody, cleanup and unknown metadata.
CREATE FUNCTION public.sandy_credential_key_version(p_resource jsonb,p_version text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
BEGIN
 IF p_resource->>'service_account' IS DISTINCT FROM 'sandy-computer@elaborate-haven-511518-a5.iam.gserviceaccount.com' OR p_version IS NULL OR p_version !~ '^projects/(elaborate-haven-511518-a5|1030223524306|-)/serviceAccounts/sandy-computer@elaborate-haven-511518-a5\.iam\.gserviceaccount\.com/keys/[a-f0-9]{20,64}$' THEN RAISE EXCEPTION 'credential_key_scope_mismatch'; END IF;
 RETURN regexp_replace(p_version,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/');
END $$;
CREATE FUNCTION public.sandy_credential_key_identity(p_resource jsonb,p_material text,p_provider_version text DEFAULT NULL) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE key jsonb; identity text;
BEGIN
 IF p_material IS NULL OR octet_length(p_material) NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION 'credential_key_format_invalid'; END IF;
 BEGIN key:=p_material::jsonb; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'credential_key_format_invalid'; END;
 IF jsonb_typeof(key) IS DISTINCT FROM 'object' OR key->>'type' IS DISTINCT FROM 'service_account' OR key->>'project_id' IS DISTINCT FROM 'elaborate-haven-511518-a5' OR key->>'client_email' IS DISTINCT FROM 'sandy-computer@elaborate-haven-511518-a5.iam.gserviceaccount.com' OR key->>'token_uri' IS DISTINCT FROM 'https://oauth2.googleapis.com/token' OR jsonb_typeof(key->'private_key_id') IS DISTINCT FROM 'string' OR key->>'private_key_id' IS NULL OR key->>'private_key_id' !~ '^[a-f0-9]{20,64}$' OR jsonb_typeof(key->'private_key') IS DISTINCT FROM 'string' OR length(key->>'private_key')<1 THEN RAISE EXCEPTION 'credential_key_scope_mismatch'; END IF;
 identity:=public.sandy_credential_key_version(p_resource,'projects/elaborate-haven-511518-a5/serviceAccounts/'||(key->>'client_email')||'/keys/'||(key->>'private_key_id'));
 IF p_provider_version IS NOT NULL AND public.sandy_credential_key_version(p_resource,p_provider_version) IS DISTINCT FROM identity THEN RAISE EXCEPTION 'credential_key_scope_mismatch'; END IF;
 RETURN identity;
END $$;
REVOKE ALL ON FUNCTION public.sandy_credential_key_version(jsonb,text),public.sandy_credential_key_identity(jsonb,text,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.sandy_credential_assert_admission(p_admission uuid,p_actor uuid,p_operation text,p_scope_sha256 text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE item public.sandy_api_execution_admissions;
BEGIN
 SELECT * INTO item FROM public.sandy_api_execution_admissions WHERE id=p_admission;
 IF NOT FOUND OR item.state<>'consumed' OR item.actor_id<>p_actor OR item.operation IS DISTINCT FROM p_operation OR item.scope_sha256 IS DISTINCT FROM p_scope_sha256 OR item.credential_id IS NOT NULL OR item.approval_id IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_actor AND role='owner' AND enabled) THEN RAISE EXCEPTION 'credential_scoped_admission_required'; END IF;
END $$;

CREATE FUNCTION public.sandy_credential_begin(p_admission uuid,p_actor uuid,p_operation text,p_target uuid,p_source_version uuid,p_scope_sha256 text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE target public.sandy_credential_targets; prior public.sandy_credential_rotations; rotation uuid;
BEGIN
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,p_operation,p_scope_sha256);
 IF p_operation IS NULL OR p_operation NOT IN ('supabase.functions.secrets.rotate','github.repo_secrets.rotate','gcp.secrets.create_version','gcp.secrets.rotate','gcp.service_accounts.keys.rotate','system.credentials.provider.rollback','system.credentials.provider.adopt','gcp.secrets.access') THEN RAISE EXCEPTION 'credential_operation_not_supported'; END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=p_target FOR UPDATE;
 IF NOT FOUND OR NOT target.enabled OR NOT target.verified OR target.scope_sha256<>p_scope_sha256 THEN RAISE EXCEPTION 'verified_credential_target_required'; END IF;
 SELECT * INTO prior FROM public.sandy_credential_rotations WHERE source_admission_id=p_admission;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'reused',true,'rotation_id',prior.id,'state',prior.state); END IF;
 IF EXISTS(SELECT 1 FROM public.sandy_credential_rotations WHERE target_id=p_target AND state IN ('claimed','accepted','unknown','cleanup_claimed','verified')) THEN RAISE EXCEPTION 'credential_rotation_requires_reconciliation'; END IF;
 IF p_source_version IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE id=p_source_version AND target_id=p_target AND state IN ('staged','retained','active')) THEN RAISE EXCEPTION 'credential_source_version_not_bound'; END IF;
 INSERT INTO public.sandy_credential_rotations(target_id,actor_id,source_admission_id,source_operation,source_version_id,prior_version_id,target_config_sha256)
 VALUES(p_target,p_actor,p_admission,p_operation,p_source_version,target.active_version_id,target.config_sha256) RETURNING id INTO rotation;
 RETURN jsonb_build_object('ok',true,'reused',false,'rotation_id',rotation,'state','claimed');
END $$;

-- The only plaintext read is purpose-bound to an admitted rotation. No arbitrary Vault ID/name is accepted.
CREATE FUNCTION public.sandy_credential_material(p_rotation uuid,p_actor uuid,p_admission uuid,p_slot text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets; version public.sandy_credential_versions; version_id uuid; material text;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation;
 IF NOT FOUND OR rotation.actor_id<>p_actor THEN RAISE EXCEPTION 'credential_rotation_not_found'; END IF;
 IF rotation.state='cleanup_claimed' THEN RAISE EXCEPTION 'credential_key_cleanup_already_claimed'; END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id;
 IF NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 THEN RAISE EXCEPTION 'credential_target_changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND actor_id=p_actor AND state='consumed' AND scope_sha256=target.scope_sha256 AND credential_id IS NULL AND approval_id IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_actor AND role='owner' AND enabled) THEN RAISE EXCEPTION 'credential_scoped_admission_required'; END IF;
 version_id:=CASE p_slot WHEN 'source' THEN rotation.source_version_id WHEN 'prior' THEN rotation.prior_version_id WHEN 'staged' THEN rotation.staged_version_id ELSE NULL END;
 SELECT * INTO version FROM public.sandy_credential_versions WHERE id=version_id AND target_id=target.id;
 IF NOT FOUND AND p_slot='source' AND (rotation.source_admission_id=p_admission OR EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND operation='system.credentials.provider.reconcile' AND state='consumed')) AND target.resource->>'source_vault_secret_id' ~ '^[a-f0-9-]{36}$' THEN
  SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=(target.resource->>'source_vault_secret_id')::uuid;
  IF material IS NULL OR octet_length(material) NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION 'credential_material_unavailable'; END IF;
  RETURN jsonb_build_object('ok',true,'value',material,'version_id',NULL,'material_sha256',encode(extensions.digest(material,'sha256'),'hex'),'provider_version_id',NULL);
 END IF;
 IF version.id IS NULL OR version.state='revoked' THEN RAISE EXCEPTION 'credential_material_unavailable'; END IF;
 IF (p_slot IN ('source','prior') AND rotation.source_admission_id<>p_admission AND NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND operation='system.credentials.provider.reconcile' AND state='consumed')) OR (p_slot='staged' AND NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND operation IN ('system.credentials.provider.verify','system.credentials.provider.activate'))) THEN RAISE EXCEPTION 'credential_material_purpose_mismatch'; END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=version.vault_secret_id;
 IF material IS NULL OR encode(extensions.digest(material,'sha256'),'hex')<>version.material_sha256 THEN RAISE EXCEPTION 'credential_custody_integrity_failed'; END IF;
 RETURN jsonb_build_object('ok',true,'value',material,'version_id',version.id,'material_sha256',version.material_sha256,'provider_version_id',version.provider_version_id);
END $$;

CREATE FUNCTION public.sandy_credential_stage(p_rotation uuid,p_actor uuid,p_admission uuid,p_material text,p_provider_version text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets; secret_id uuid; version_id uuid; digest text;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 IF NOT FOUND OR rotation.actor_id<>p_actor OR (rotation.source_admission_id<>p_admission AND NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND operation='system.credentials.provider.reconcile' AND state='consumed')) OR rotation.state NOT IN ('claimed','unknown') OR rotation.staged_version_id IS NOT NULL THEN RAISE EXCEPTION 'credential_rotation_stage_refused'; END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,(SELECT operation FROM public.sandy_api_execution_admissions WHERE id=p_admission),target.scope_sha256);
 IF NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 OR p_material IS NULL OR octet_length(p_material) NOT BETWEEN 1 AND 65536 OR length(coalesce(p_provider_version,''))>1000 THEN RAISE EXCEPTION 'credential_rotation_stage_refused'; END IF;
 IF target.provider='gcp_service_account_key' THEN
  p_provider_version:=public.sandy_credential_key_identity(target.resource,p_material,p_provider_version);
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('sandy_credential_provider_key:'||regexp_replace(p_provider_version,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/'),0));
  IF EXISTS(SELECT 1 FROM public.sandy_credential_rotations WHERE state='cleanup_claimed' AND regexp_replace(provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/')=regexp_replace(p_provider_version,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/')) THEN RAISE EXCEPTION 'credential_key_cleanup_already_claimed'; END IF;
 END IF;
 digest:=encode(extensions.digest(p_material,'sha256'),'hex');
 secret_id:=vault.create_secret(p_material,'SANDY_CUSTODY_'||rotation.id::text,'Sandy encrypted provider custody');
 INSERT INTO public.sandy_credential_versions(target_id,vault_secret_id,material_sha256,provider_version_id,state,source_admission_id)
 VALUES(target.id,secret_id,digest,p_provider_version,'staged',p_admission) RETURNING id INTO version_id;
 UPDATE public.sandy_credential_rotations SET staged_version_id=version_id,provider_version_id=p_provider_version,state='accepted',updated_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'rotation_id',rotation.id,'version_id',version_id,'material_sha256',digest,'provider_version_id',p_provider_version,'state','accepted');
END $$;

CREATE FUNCTION public.sandy_credential_record_unknown(p_rotation uuid,p_actor uuid,p_admission uuid,p_provider_version text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 IF rotation.id IS NULL OR rotation.actor_id<>p_actor OR rotation.source_admission_id<>p_admission OR rotation.state NOT IN ('claimed','accepted') THEN RAISE EXCEPTION 'credential_rotation_not_bound'; END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,rotation.source_operation,target.scope_sha256);
 IF p_provider_version IS NOT NULL AND target.provider='gcp_service_account_key' THEN p_provider_version:=public.sandy_credential_key_version(target.resource,p_provider_version); END IF;
 UPDATE public.sandy_credential_rotations SET provider_version_id=CASE WHEN p_provider_version ~ '^projects/(elaborate-haven-511518-a5|1030223524306)/' AND length(p_provider_version)<=1000 THEN coalesce(provider_version_id,p_provider_version) ELSE provider_version_id END,state='unknown',updated_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'rotation_id',p_rotation,'state','unknown','redispatch_permitted',false);
END $$;

-- A provider verification is its own successful read admission. Exact canonical
-- evidence must match the shared receipt digest; callers cannot supply a boolean proof.
CREATE FUNCTION public.sandy_credential_activate(p_rotation uuid,p_actor uuid,p_admission uuid,p_verification_admission uuid,p_evidence jsonb,p_evidence_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets; version public.sandy_credential_versions; proof public.sandy_api_execution_admissions; digest text;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 IF NOT FOUND OR rotation.actor_id<>p_actor OR rotation.state NOT IN ('accepted','unknown','verified') THEN RAISE EXCEPTION 'credential_activation_refused'; END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id FOR UPDATE;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'system.credentials.provider.activate',target.scope_sha256);
 IF NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 OR target.active_version_id IS DISTINCT FROM rotation.prior_version_id THEN RAISE EXCEPTION 'credential_preimage_changed'; END IF;
 SELECT * INTO version FROM public.sandy_credential_versions WHERE id=rotation.staged_version_id AND target_id=target.id AND state='staged';
 IF NOT FOUND THEN RAISE EXCEPTION 'credential_staged_material_required'; END IF;
 SELECT * INTO proof FROM public.sandy_api_execution_admissions WHERE id=p_verification_admission;
 digest:=encode(extensions.digest(p_evidence_canonical,'sha256'),'hex');
 IF p_evidence IS NULL OR p_evidence_canonical IS NULL OR p_evidence_canonical::jsonb<>p_evidence OR proof.id IS NULL OR proof.actor_id<>p_actor OR proof.operation IS DISTINCT FROM 'system.credentials.provider.verify' OR proof.state IS DISTINCT FROM 'succeeded' OR proof.credential_id IS NOT NULL OR proof.approval_id IS NULL OR proof.scope_sha256 IS DISTINCT FROM target.scope_sha256 OR proof.result_sha256 IS DISTINCT FROM digest OR proof.finished_at IS NULL OR proof.finished_at<clock_timestamp()-interval '5 minutes'
 OR p_evidence->>'rotation_id' IS DISTINCT FROM rotation.id::text OR p_evidence->>'target_id' IS DISTINCT FROM target.id::text OR p_evidence->>'material_sha256' IS DISTINCT FROM version.material_sha256 OR p_evidence->>'target_config_sha256' IS DISTINCT FROM target.config_sha256 OR p_evidence->>'provider_verified' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'credential_live_readback_required'; END IF;
 UPDATE public.sandy_credential_versions SET state='retained' WHERE id=target.active_version_id AND state='active';
 UPDATE public.sandy_credential_versions SET state='active' WHERE id=version.id;
 UPDATE public.sandy_credential_targets SET active_version_id=version.id WHERE id=target.id;
 UPDATE public.sandy_credential_rotations SET state='activated',verification_admission_id=proof.id,updated_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'rotation_id',rotation.id,'target_id',target.id,'active_version_id',version.id,'retained_version_id',rotation.prior_version_id,'provider_readback_verified',true,'previous_credential_revoked',false);
END $$;

CREATE FUNCTION public.sandy_credential_record_failed(p_rotation uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND actor_id=p_actor AND state='consumed') THEN RAISE EXCEPTION 'credential_scoped_admission_required'; END IF;
 UPDATE public.sandy_credential_rotations SET state='failed',updated_at=clock_timestamp() WHERE id=p_rotation AND actor_id=p_actor AND source_admission_id=p_admission AND state='claimed' AND staged_version_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'credential_failure_requires_reconciliation'; END IF;
 RETURN jsonb_build_object('ok',true,'rotation_id',p_rotation,'state','failed','redispatch_permitted',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_credential_record_failed(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_credential_record_failed(uuid,uuid,uuid) TO service_role;

CREATE FUNCTION public.sandy_credential_record_verification(p_rotation uuid,p_actor uuid,p_admission uuid,p_evidence jsonb,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets; version public.sandy_credential_versions; proof public.sandy_api_execution_admissions;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 IF NOT FOUND OR rotation.actor_id<>p_actor OR rotation.state NOT IN ('accepted','unknown','verified') THEN RAISE EXCEPTION 'credential_verification_refused'; END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id;
 SELECT * INTO version FROM public.sandy_credential_versions WHERE id=rotation.staged_version_id AND target_id=target.id;
 SELECT * INTO proof FROM public.sandy_api_execution_admissions WHERE id=p_admission;
 IF p_evidence IS NULL OR p_canonical IS NULL OR version.id IS NULL OR NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 OR proof.id IS NULL OR proof.actor_id<>p_actor OR proof.operation IS DISTINCT FROM 'system.credentials.provider.verify' OR proof.state IS DISTINCT FROM 'succeeded' OR proof.credential_id IS NOT NULL OR proof.approval_id IS NULL OR proof.scope_sha256 IS DISTINCT FROM target.scope_sha256 OR proof.result_sha256 IS DISTINCT FROM encode(extensions.digest(p_canonical,'sha256'),'hex') OR NOT EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_actor AND role='owner' AND enabled) OR proof.finished_at IS NULL OR proof.finished_at<clock_timestamp()-interval '5 minutes' OR p_canonical::jsonb<>p_evidence OR p_evidence->>'rotation_id' IS DISTINCT FROM rotation.id::text OR p_evidence->>'target_id' IS DISTINCT FROM target.id::text OR p_evidence->>'material_sha256' IS DISTINCT FROM version.material_sha256 OR p_evidence->>'target_config_sha256' IS DISTINCT FROM target.config_sha256 OR p_evidence->>'provider_verified' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'credential_live_readback_required'; END IF;
 UPDATE public.sandy_credential_rotations SET state='verified',verification_admission_id=proof.id,verification_evidence=p_evidence,verification_canonical=p_canonical,updated_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'rotation_id',rotation.id,'verification_admission_id',proof.id,'provider_verified',true);
END $$;
CREATE FUNCTION public.sandy_credential_revoke_material(p_target uuid,p_version uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE target public.sandy_credential_targets; version public.sandy_credential_versions; material text;
BEGIN
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=p_target;
 IF NOT FOUND OR NOT target.enabled OR NOT target.verified THEN RAISE EXCEPTION 'verified_credential_target_required'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'system.credentials.provider.revoke',target.scope_sha256);
 SELECT * INTO version FROM public.sandy_credential_versions WHERE id=p_version AND target_id=p_target AND state IN ('active','retained');
 IF NOT FOUND THEN RAISE EXCEPTION 'credential_version_not_bound'; END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=version.vault_secret_id;
 IF material IS NULL OR encode(extensions.digest(material,'sha256'),'hex')<>version.material_sha256 THEN RAISE EXCEPTION 'credential_custody_integrity_failed'; END IF;
 RETURN jsonb_build_object('ok',true,'value',material,'version_id',version.id,'material_sha256',version.material_sha256,'provider_version_id',version.provider_version_id);
END $$;
CREATE FUNCTION public.sandy_credential_record_revocation(p_target uuid,p_version uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE target public.sandy_credential_targets;
BEGIN
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=p_target FOR UPDATE;
 IF NOT FOUND OR NOT target.enabled OR NOT target.verified THEN RAISE EXCEPTION 'verified_credential_target_required'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'system.credentials.provider.revoke',target.scope_sha256);
 IF target.active_version_id=p_version THEN RAISE EXCEPTION 'active_credential_cannot_be_revoked'; END IF;
 UPDATE public.sandy_credential_versions SET state='revoked' WHERE id=p_version AND target_id=p_target AND state='retained';
 IF NOT FOUND THEN RAISE EXCEPTION 'retained_credential_required'; END IF;
 RETURN jsonb_build_object('ok',true,'version_id',p_version,'provider_revocation_observed',true,'custody_deleted',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_credential_record_verification(uuid,uuid,uuid,jsonb,text),public.sandy_credential_revoke_material(uuid,uuid,uuid,uuid),public.sandy_credential_record_revocation(uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_credential_record_verification(uuid,uuid,uuid,jsonb,text),public.sandy_credential_revoke_material(uuid,uuid,uuid,uuid),public.sandy_credential_record_revocation(uuid,uuid,uuid,uuid) TO service_role;

CREATE FUNCTION public.sandy_credential_probe_start(p_rotation uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id;
 IF rotation.id IS NULL OR rotation.actor_id<>p_actor OR rotation.staged_version_id IS NULL OR rotation.state NOT IN ('accepted','unknown','verified') OR target.provider<>'github_actions_secret' OR NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 THEN RAISE EXCEPTION 'credential_probe_binding_required'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,(SELECT operation FROM public.sandy_api_execution_admissions WHERE id=p_admission),target.scope_sha256);
 IF p_admission<>rotation.source_admission_id AND NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=p_admission AND operation='system.credentials.provider.reconcile') THEN RAISE EXCEPTION 'credential_probe_admission_mismatch'; END IF;
 IF rotation.probe_started_at IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'started',false,'reused',true); END IF;
 UPDATE public.sandy_credential_rotations SET probe_started_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'started',true,'reused',false);
END $$;
-- A committed cleanup claim excludes any late Vault stage before provider disable.
-- The per-key lock also interlocks staging/adoption through another target.
CREATE FUNCTION public.sandy_credential_claim_unstaged_key(p_rotation uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets; prior public.sandy_credential_versions;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id FOR UPDATE;
 SELECT * INTO prior FROM public.sandy_credential_versions WHERE id=rotation.prior_version_id;
 IF rotation.id IS NULL OR rotation.actor_id<>p_actor OR rotation.state NOT IN ('unknown','cleanup_claimed') OR rotation.staged_version_id IS NOT NULL OR target.provider<>'gcp_service_account_key' OR NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 OR target.active_version_id IS DISTINCT FROM rotation.prior_version_id OR rotation.provider_version_id IS NULL OR prior.provider_version_id IS NULL OR rotation.provider_version_id=prior.provider_version_id OR NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions WHERE id=rotation.source_admission_id AND operation='gcp.service_accounts.keys.rotate') THEN RAISE EXCEPTION 'credential_unstaged_key_identity_unconfirmed'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'system.credentials.provider.reconcile',target.scope_sha256);
 rotation.provider_version_id:=public.sandy_credential_key_version(target.resource,rotation.provider_version_id);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('sandy_credential_provider_key:'||regexp_replace(rotation.provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/'),0));
 IF EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE state IN ('staged','active','retained') AND regexp_replace(provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/')=regexp_replace(rotation.provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/')) THEN RAISE EXCEPTION 'credential_custodied_key_cannot_be_cleaned'; END IF;
 IF rotation.state='cleanup_claimed' THEN
  -- A later approved reconcile may observe only. It never rebinds or redispatches.
  RETURN jsonb_build_object('ok',true,'claimed',true,'dispatch_allowed',false,'rotation_id',rotation.id,'target_id',target.id,'provider_version_id',rotation.provider_version_id);
 END IF;
 UPDATE public.sandy_credential_rotations SET state='cleanup_claimed',cleanup_admission_id=p_admission,updated_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'claimed',true,'dispatch_allowed',true,'rotation_id',rotation.id,'target_id',target.id,'provider_version_id',rotation.provider_version_id);
END $$;
CREATE FUNCTION public.sandy_credential_resolve_unstaged_key(p_rotation uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rotation public.sandy_credential_rotations; target public.sandy_credential_targets;
BEGIN
 SELECT * INTO rotation FROM public.sandy_credential_rotations WHERE id=p_rotation FOR UPDATE;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=rotation.target_id FOR UPDATE;
 IF rotation.id IS NULL OR rotation.actor_id<>p_actor OR rotation.state<>'cleanup_claimed' OR rotation.cleanup_admission_id IS NULL OR rotation.staged_version_id IS NOT NULL OR target.provider<>'gcp_service_account_key' OR NOT target.enabled OR NOT target.verified OR target.config_sha256<>rotation.target_config_sha256 OR target.active_version_id IS DISTINCT FROM rotation.prior_version_id THEN RAISE EXCEPTION 'credential_unstaged_key_identity_unconfirmed'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'system.credentials.provider.reconcile',target.scope_sha256);
 rotation.provider_version_id:=public.sandy_credential_key_version(target.resource,rotation.provider_version_id);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('sandy_credential_provider_key:'||regexp_replace(rotation.provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/'),0));
 IF EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE state IN ('staged','active','retained') AND regexp_replace(provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/')=regexp_replace(rotation.provider_version_id,'^projects/(1030223524306|-)/','projects/elaborate-haven-511518-a5/')) THEN RAISE EXCEPTION 'credential_custodied_key_cannot_be_cleaned'; END IF;
 UPDATE public.sandy_credential_rotations SET state='failed',updated_at=clock_timestamp() WHERE id=rotation.id;
 RETURN jsonb_build_object('ok',true,'rotation_id',rotation.id,'target_id',target.id,'provider_version_id',rotation.provider_version_id,'reconciliation_required',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_credential_probe_start(uuid,uuid,uuid),public.sandy_credential_claim_unstaged_key(uuid,uuid,uuid),public.sandy_credential_resolve_unstaged_key(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_credential_probe_start(uuid,uuid,uuid),public.sandy_credential_claim_unstaged_key(uuid,uuid,uuid),public.sandy_credential_resolve_unstaged_key(uuid,uuid,uuid) TO service_role;

CREATE FUNCTION public.sandy_credential_store_version(p_target uuid,p_actor uuid,p_admission uuid,p_material text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE target public.sandy_credential_targets; secret_id uuid; version_id uuid; provider_version text;
BEGIN
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=p_target FOR UPDATE;
 IF NOT FOUND OR NOT target.enabled OR NOT target.verified OR p_material IS NULL OR octet_length(p_material) NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION 'verified_credential_target_required'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'supabase.vault.secrets.create_version',target.scope_sha256);
 IF EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE source_admission_id=p_admission) THEN RAISE EXCEPTION 'credential_version_already_recorded'; END IF;
 IF target.provider='gcp_service_account_key' THEN
  provider_version:=public.sandy_credential_key_identity(target.resource,p_material);
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('sandy_credential_provider_key:'||provider_version,0));
  IF EXISTS(SELECT 1 FROM public.sandy_credential_rotations WHERE state='cleanup_claimed' AND provider_version_id=provider_version) THEN RAISE EXCEPTION 'credential_key_cleanup_already_claimed'; END IF;
 END IF;
 secret_id:=vault.create_secret(p_material,'SANDY_CUSTODY_'||gen_random_uuid()::text,'Sandy encrypted staged credential');
 INSERT INTO public.sandy_credential_versions(target_id,vault_secret_id,material_sha256,provider_version_id,state,source_admission_id) VALUES(target.id,secret_id,encode(extensions.digest(p_material,'sha256'),'hex'),provider_version,'staged',p_admission) RETURNING id INTO version_id;
 RETURN jsonb_build_object('ok',true,'target_id',target.id,'version_id',version_id,'encrypted_at_rest',true,'active',false);
END $$;
CREATE FUNCTION public.sandy_credential_delete_staged(p_target uuid,p_version uuid,p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE target public.sandy_credential_targets; version public.sandy_credential_versions;
BEGIN
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=p_target FOR UPDATE;
 IF NOT FOUND OR NOT target.enabled OR NOT target.verified THEN RAISE EXCEPTION 'verified_credential_target_required'; END IF;
 PERFORM public.sandy_credential_assert_admission(p_admission,p_actor,'supabase.vault.secrets.delete',target.scope_sha256);
 SELECT * INTO version FROM public.sandy_credential_versions WHERE id=p_version AND target_id=p_target AND state='staged' FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.sandy_credential_rotations WHERE source_version_id=p_version OR staged_version_id=p_version OR prior_version_id=p_version) OR target.active_version_id=p_version THEN RAISE EXCEPTION 'credential_version_in_use'; END IF;
 DELETE FROM vault.secrets WHERE id=version.vault_secret_id;
 UPDATE public.sandy_credential_versions SET state='revoked' WHERE id=version.id;
 RETURN jsonb_build_object('ok',true,'version_id',version.id,'custody_deleted',true,'provider_credential_revoked',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_credential_store_version(uuid,uuid,uuid,text),public.sandy_credential_delete_staged(uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_credential_store_version(uuid,uuid,uuid,text),public.sandy_credential_delete_staged(uuid,uuid,uuid,uuid) TO service_role;

REVOKE ALL ON FUNCTION public.sandy_credential_assert_admission(uuid,uuid,text,text),public.sandy_credential_begin(uuid,uuid,text,uuid,uuid,text),public.sandy_credential_material(uuid,uuid,uuid,text),public.sandy_credential_stage(uuid,uuid,uuid,text,text),public.sandy_credential_record_unknown(uuid,uuid,uuid,text),public.sandy_credential_activate(uuid,uuid,uuid,uuid,jsonb,text) FROM PUBLIC,anon,authenticated,service_role;
